1	import { generateLean, generateLeanStreaming, verifyLean } from "./api";
2	
3	export const MAX_LEAN_ATTEMPTS = 3;
4	
5	export type LeanRetryCallbacks = {
6	  /** Called with each new Lean code attempt */
7	  onLeanCode: (code: string) => void;
8	  /** Called when verification errors occur */
9	  onErrors: (errors: string) => void;
10	  /** Called on each attempt start (attempt >= 2 means retry) */
11	  onAttemptStart?: (attempt: number) => void;
12	  /** Called before verification starts */
13	  onVerifyStart?: (attempt: number) => void;
14	  /** Optional: check if execution should be cancelled */
15	  isCancelled?: () => boolean;
16	  /** Optional: Lean dependency context to prepend for verification */
17	  dependencyContext?: string;
18	  /** Called with accumulated text as tokens stream in */
19	  onToken?: (accumulated: string) => void;
20	};
21	
22	export type LeanRetryResult = {
23	  valid: boolean;
24	  code: string;
25	  errors: string;
26	  /** True when the verifier was unavailable — the proof was generated but never checked. */
27	  unavailable?: boolean;
28	};
29	
30	/**
31	 * Generate Lean code from a semiformal proof and verify it,
32	 * retrying up to MAX_LEAN_ATTEMPTS times on failure.
33	 */
34	export async function leanRetryLoop(
35	  semiformal: string,
36	  callbacks: LeanRetryCallbacks,
37	): Promise<LeanRetryResult> {
38	  const { onLeanCode, onErrors, onAttemptStart, onVerifyStart, isCancelled, dependencyContext, onToken } = callbacks;
39	
40	  let currentCode = "";
41	  let lastErrors = "";
42	
43	  for (let attempt = 1; attempt <= MAX_LEAN_ATTEMPTS; attempt++) {
44	    if (isCancelled?.()) {
45	      return { valid: false, code: currentCode, errors: "" };
46	    }
47	
48	    onAttemptStart?.(attempt);
49	
50	    const isRetry = attempt > 1;
51	    const args = [
52	      semiformal,
53	      isRetry ? currentCode : undefined,
54	      isRetry ? lastErrors : undefined,
55	      undefined,
56	      dependencyContext || undefined,
57	    ] as const;
58	
59	    currentCode = onToken
60	      ? await generateLeanStreaming(...args, onToken)
61	      : await generateLean(...args);
62	    onLeanCode(currentCode);
63	
64	    if (isCancelled?.()) {
65	      return { valid: false, code: currentCode, errors: "" };
66	    }
67	
68	    onVerifyStart?.(attempt);
69	
70	    const fullCode = dependencyContext ? `${dependencyContext}\n\n${currentCode}` : currentCode;
71	    const { valid, errors, unavailable } = await verifyLean(fullCode);
72	
73	    if (unavailable) {
74	      // No point retrying — the proof was never actually checked.
75	      onErrors("");
76	      return { valid: false, code: currentCode, errors: "", unavailable: true };
77	    }
78	
79	    if (valid) {
80	      onErrors("");
81	      return { valid: true, code: currentCode, errors: "" };
82	    }
83	
84	    lastErrors = errors || "Verification failed";
85	    onErrors(lastErrors);
86	  }
87	
88	  return { valid: false, code: currentCode, errors: lastErrors };
89	}
