1	"use client";
2	
3	import { useState, useCallback, useRef } from "react";
4	import { generateSemiformalStreaming, generateLeanStreaming, verifyLean, verifyResultToStatus } from "@/app/lib/formalization/api";
5	import { leanRetryLoop } from "@/app/lib/formalization/leanRetryLoop";
6	import { throttle } from "@/app/lib/utils/throttle";
7	import type { LoadingPhase, VerificationStatus } from "@/app/lib/types/session";
8	
9	export type { LoadingPhase, VerificationStatus };
10	
11	/**
12	 * Callbacks the pipeline uses to read/write state.
13	 * The caller provides these so the same pipeline logic works
14	 * for both global state and per-node state.
15	 */
16	export type PipelineAccessors = {
17	  getSemiformal: () => string;
18	  setSemiformal: (text: string) => void;
19	  getLeanCode: () => string;
20	  setLeanCode: (code: string) => void;
21	  setVerificationStatus: (status: VerificationStatus) => void;
22	  getVerificationErrors: () => string;
23	  setVerificationErrors: (errors: string) => void;
24	  /** Called before semiformal generation to reset related state */
25	  onResetForSemiformal?: () => void;
26	  /** Called before lean generation to reset related state */
27	  onResetForLean?: () => void;
28	  /** Optional: return dependency Lean context for verification */
29	  getDependencyContext?: () => string | undefined;
30	  /** Optional: mirror updates to session storage */
31	  onSessionUpdate?: (updates: Record<string, unknown>) => void;
32	};
33	
34	export type FormalizationPipeline = {
35	  loadingPhase: LoadingPhase;
36	  handleGenerateSemiformal: (inputText: string) => Promise<void>;
37	  handleGenerateLean: () => Promise<void>;
38	  handleReVerify: () => Promise<void>;
39	  handleLeanIterate: (instruction: string) => Promise<void>;
40	  handleRegenerateLean: () => void;
41	};
42	
43	/**
44	 * Encapsulates the semiformal → Lean → verify → retry pipeline.
45	 *
46	 * Accessors are passed via a ref so the pipeline always reads the latest
47	 * state without needing to re-create callbacks when accessors change.
48	 */
49	export function useFormalizationPipeline(accessors: PipelineAccessors): FormalizationPipeline {
50	  const [loadingPhase, setLoadingPhase] = useState<LoadingPhase>("idle");
51	
52	  // Keep a ref to accessors so async callbacks always see the latest version
53	  const acc = useRef(accessors);
54	  acc.current = accessors;
55	
56	  const handleGenerateSemiformal = useCallback(async (inputText: string) => {
57	    const a = acc.current;
58	    a.onResetForSemiformal?.();
59	    a.setSemiformal("");
60	    a.setLeanCode("");
61	    a.setVerificationStatus("none");
62	    a.setVerificationErrors("");
63	    setLoadingPhase("semiformal");
64	
65	    try {
66	      const onToken = throttle((accumulated: string) => {
67	        acc.current.setSemiformal(accumulated);
68	      }, 50);
69	
70	      const proof = await generateSemiformalStreaming(inputText, undefined, onToken);
71	      a.setSemiformal(proof);
72	      a.onSessionUpdate?.({ semiformalText: proof });
73	    } catch (err) {
74	      const msg = err instanceof Error ? err.message : "Request failed";
75	      a.setSemiformal(`Error: ${msg}`);
76	    } finally {
77	      setLoadingPhase("idle");
78	    }
79	  }, []);
80	
81	  const handleGenerateLean = useCallback(async () => {
82	    const a = acc.current;
83	    const semiformal = a.getSemiformal();
84	    if (!semiformal) return;
85	
86	    a.onResetForLean?.();
87	    a.setLeanCode("");
88	    a.setVerificationStatus("none");
89	    a.setVerificationErrors("");
90	    setLoadingPhase("lean");
91	
92	    try {
93	      const depContext = a.getDependencyContext?.();
94	
95	      const onToken = throttle((accumulated: string) => {
96	        acc.current.setLeanCode(accumulated);
97	      }, 50);
98	
99	      const result = await leanRetryLoop(semiformal, {
100	        onLeanCode: (code) => {
101	          onToken.cancel();
102	          a.setLeanCode(code);
103	          a.onSessionUpdate?.({ leanCode: code });
104	        },
105	        onErrors: (errors) => {
106	          a.setVerificationErrors(errors);
107	          a.onSessionUpdate?.({ verificationErrors: errors });
108	        },
109	        onAttemptStart: (attempt) => {
110	          if (attempt > 1) setLoadingPhase("retrying");
111	        },
112	        onVerifyStart: (attempt) => {
113	          setLoadingPhase(attempt > 1 ? "reverifying" : "verifying");
114	          a.setVerificationStatus("verifying");
115	          a.onSessionUpdate?.({ verificationStatus: "verifying" });
116	        },
117	        dependencyContext: depContext || undefined,
118	        onToken,
119	      });
120	
121	      const vStatus = verifyResultToStatus(result);
122	      // Only "invalid" carries verifier output; "valid"/"unavailable" clear errors.
123	      const vErrors = vStatus === "invalid" ? result.errors : "";
124	      a.setVerificationStatus(vStatus);
125	      if (vStatus !== "invalid") a.setVerificationErrors("");
126	      a.onSessionUpdate?.({ verificationStatus: vStatus, verificationErrors: vErrors });
127	    } catch (err) {
128	      const msg = err instanceof Error ? err.message : "Request failed";
129	      const currentLean = a.getLeanCode();
130	      if (!currentLean) a.setLeanCode(`-- Error: ${msg}`);
131	      else { a.setVerificationStatus("invalid"); a.setVerificationErrors(msg); }
132	      a.onSessionUpdate?.({ verificationStatus: "invalid", verificationErrors: msg });
133	    } finally {
134	      setLoadingPhase("idle");
135	    }
136	  }, []);
137	
138	  /** Prepend dependency context, verify, and apply result to state */
139	  const verifyWithDeps = useCallback(async (a: PipelineAccessors, code: string) => {
140	    const depContext = a.getDependencyContext?.();
141	    const fullCode = depContext ? `${depContext}\n\n${code}` : code;
142	    const result = await verifyLean(fullCode);
143	    const vStatus = verifyResultToStatus(result);
144	    const vErrors = vStatus === "invalid" ? (result.errors || "Verification failed") : "";
145	    a.setVerificationStatus(vStatus);
146	    a.setVerificationErrors(vErrors);
147	    a.onSessionUpdate?.({ verificationStatus: vStatus, verificationErrors: vErrors });
148	  }, []);
149	
150	  const handleReVerify = useCallback(async () => {
151	    const a = acc.current;
152	    const code = a.getLeanCode();
153	    if (!code) return;
154	
155	    setLoadingPhase("verifying");
156	    a.setVerificationStatus("verifying");
157	    a.setVerificationErrors("");
158	    a.onSessionUpdate?.({ verificationStatus: "verifying", verificationErrors: "" });
159	
160	    try {
161	      await verifyWithDeps(a, code);
162	    } catch (err) {
163	      const msg = err instanceof Error ? err.message : "Verification request failed";
164	      a.setVerificationStatus("invalid");
165	      a.setVerificationErrors(msg);
166	      a.onSessionUpdate?.({ verificationStatus: "invalid", verificationErrors: msg });
167	    } finally {
168	      setLoadingPhase("idle");
169	    }
170	  }, [verifyWithDeps]);
171	
172	  const handleLeanIterate = useCallback(async (instruction: string) => {
173	    const a = acc.current;
174	    const semiformal = a.getSemiformal();
175	    const currentLean = a.getLeanCode();
176	    const currentErrors = a.getVerificationErrors();
177	    if (!semiformal) return;
178	
179	    setLoadingPhase("iterating");
180	    a.setVerificationStatus("verifying");
181	    a.setVerificationErrors("");
182	    a.onSessionUpdate?.({ verificationStatus: "verifying", verificationErrors: "" });
183	
184	    try {
185	      const depContext = a.getDependencyContext?.();
186	
187	      const onToken = throttle((accumulated: string) => {
188	        acc.current.setLeanCode(accumulated);
189	      }, 50);
190	
191	      const newCode = await generateLeanStreaming(
192	        semiformal,
193	        currentLean || undefined,
194	        currentErrors || undefined,
195	        instruction || undefined,
196	        depContext || undefined,
197	        onToken,
198	      );
199	
200	      a.setLeanCode(newCode);
201	      a.onSessionUpdate?.({ leanCode: newCode });
202	
203	      await verifyWithDeps(a, newCode);
204	    } catch (err) {
205	      const msg = err instanceof Error ? err.message : "Iteration failed";
206	      a.setVerificationStatus("invalid");
207	      a.setVerificationErrors(msg);
208	      a.onSessionUpdate?.({ verificationStatus: "invalid", verificationErrors: msg });
209	    } finally {
210	      setLoadingPhase("idle");
211	    }
212	  }, [verifyWithDeps]);
213	
214	  const handleRegenerateLean = useCallback(() => {
215	    handleLeanIterate("");
216	  }, [handleLeanIterate]);
217	
218	  return {
219	    loadingPhase,
220	    handleGenerateSemiformal,
221	    handleGenerateLean,
222	    handleReVerify,
223	    handleLeanIterate,
224	    handleRegenerateLean,
225	  };
226	}
