29	export function useAutoFormalizeQueue(
30	  nodes: PropositionNode[],
31	  updateNode: (id: string, updates: Partial<PropositionNode>) => void,
32	  contextText?: string,
33	) {
34	  const [progress, setProgress] = useState<QueueProgress>(INITIAL_PROGRESS);
35	
36	  // Refs for pause/cancel to avoid stale closures in the async loop
37	  const pauseRef = useRef(false);
38	  const cancelSignalRef = useRef<CancelSignal>({ cancelled: false });
39	  const runningRef = useRef(false);
40	  // Sync contextText to a ref so the async start() loop always reads the latest
41	  // value without needing contextText in its dependency array (which would
42	  // recreate start on every keystroke). Mid-run context changes apply to the
43	  // next node, not the one currently being formalized.
44	  const contextTextRef = useRef(contextText);
45	  useEffect(() => { contextTextRef.current = contextText; }, [contextText]);
46	
47	  const start = useCallback(async (artifactTypes?: ArtifactType[]) => {
48	    if (runningRef.current) return;
49	    runningRef.current = true;
50	    pauseRef.current = false;
51	    cancelSignalRef.current = { cancelled: false };
52	
53	    const sorted = topologicalSort(nodes);
54	
55	    // Filter to only unverified nodes
56	    const nodeMap = new Map(nodes.map((n) => [n.id, n]));
57	    const toProcess = sorted.filter((id) => {
58	      const n = nodeMap.get(id);
59	      return n && n.verificationStatus !== "verified";
60	    });
61	
62	    setProgress({
63	      status: "running",
64	      total: toProcess.length,
65	      completed: 0,
66	      failed: 0,
67	      skipped: 0,
68	      currentNodeId: null,
69	    });
70	
71	    // Track which nodes failed so we can skip dependents
72	    const failedIds = new Set<string>();
73	
74	    let completed = 0;
75	    let failed = 0;
76	    let skipped = 0;
77	
78	    for (const nodeId of toProcess) {
79	      // Check cancel
80	      if (cancelSignalRef.current.cancelled) break;
81	
82	      // Check pause — wait until resumed or cancelled
83	      if (pauseRef.current) {
84	        setProgress((p) => ({ ...p, status: "paused", currentNodeId: null }));
85	        await new Promise<void>((resolve) => {
86	          const check = () => {
87	            if (!pauseRef.current || cancelSignalRef.current.cancelled) {
88	              resolve();
89	            } else {
90	              setTimeout(check, 200);
91	            }
92	          };
93	          check();
94	        });
95	        if (cancelSignalRef.current.cancelled) break;
96	        setProgress((p) => ({ ...p, status: "running" }));
97	      }
98	
99	      // Re-read node state from the latest nodes array via the map
100	      // Note: we use the nodeMap built at start time for dependency checks.
101	      // The actual node data for formalization will be read fresh below.
102	      const node = nodeMap.get(nodeId);
103	      if (!node) continue;
104	
105	      // Skip if already verified (may have been verified by a resumed queue)
106	      if (node.verificationStatus === "verified") {
107	        completed++;
108	        setProgress((p) => ({ ...p, completed }));
109	        continue;
110	      }
111	
112	      // Check if any dependency failed — skip this node
113	      const hasFailedDep = node.dependsOn.some((depId) => failedIds.has(depId));
114	      if (hasFailedDep) {
115	        const failedDepId = node.dependsOn.find((depId) => failedIds.has(depId));
116	        updateNode(nodeId, {
117	          verificationStatus: "failed",
118	          verificationErrors: `Skipped: dependency ${failedDepId} failed`,
119	        });
120	        failedIds.add(nodeId);
121	        skipped++;
122	        setProgress((p) => ({ ...p, skipped }));
123	        continue;
124	      }
125	
126	      setProgress((p) => ({ ...p, currentNodeId: nodeId }));
127	
128	      const result = await formalizeNode(node, nodes, updateNode, cancelSignalRef.current, artifactTypes, contextTextRef.current);
129	
130	      if (cancelSignalRef.current.cancelled) break;
131	
132	      if (result === "verified") {
133	        completed++;
134	        setProgress((p) => ({ ...p, completed }));
135	      } else {
136	        failedIds.add(nodeId);
137	        failed++;
138	        setProgress((p) => ({ ...p, failed }));
139	      }
140	    }
141	
142	    runningRef.current = false;
143	    setProgress((p) => ({
144	      ...p,
145	      status: "done",
146	      currentNodeId: null,
147	    }));
148	  }, [nodes, updateNode]);
149	
150	  const pause = useCallback(() => {
151	    pauseRef.current = true;
152	  }, []);
153	
154	  const resume = useCallback(() => {
155	    pauseRef.current = false;
156	  }, []);
157	
158	  const cancel = useCallback(() => {
159	    cancelSignalRef.current.cancelled = true;
160	    pauseRef.current = false; // unblock if paused
161	    runningRef.current = false;
162	    setProgress((p) => ({ ...p, status: "done", currentNodeId: null }));
163	  }, []);
164	
165	  return { progress, start, pause, resume, cancel };
166	}
