10	export function buildUserMessage(req: ArtifactGenerationRequest): string {
11	  const parts: string[] = [];
12	
13	  if (req.context) {
14	    parts.push(`[Context]\n${req.context}`);
15	  }
16	
17	  if (req.nodeId && req.nodeLabel) {
18	    parts.push(`[Node: ${req.nodeLabel}]`);
19	  }
20	
21	  parts.push(`[Source Text]\n${req.sourceText}`);
22	
23	  if (req.previousAttempt) {
24	    parts.push(`[Previous Attempt — refine this]\n${req.previousAttempt}`);
25	  }
26	
27	  if (req.instruction) {
28	    parts.push(`[Additional Instruction]\n${req.instruction}`);
29	  }
30	
31	  return parts.join("\n\n");
32	}
