34	type ArtifactRouteConfig = {
35	  endpoint: string;
36	  systemPrompt: string;
37	  responseKey: string;
38	  mockResponse: (sourceText: string) => unknown;
39	  maxTokens?: number;
40	  /** How to parse the LLM response. Default: "json" (parse as JSON). "text" returns raw text. */
41	  parseResponse?: "json" | "text";
42	  /** When provided, enforces structured JSON output via OpenRouter's response_format. */
43	  responseFormat?: ResponseFormat;
44	  /** Optional: transform the request body before building the user message (e.g. legacy field mapping). */
45	  transformBody?: (body: Record<string, unknown>) => ArtifactGenerationRequest;
46	};
47	
48	/**
49	 * Generic POST handler for artifact generation routes.
50	 * Parses the uniform ArtifactGenerationRequest, calls callLlm(), parses JSON response.
51	 */
52	export async function handleArtifactRoute(
53	  request: NextRequest,
54	  config: ArtifactRouteConfig,
55	): Promise<NextResponse> {
56	  const rawBody = await request.json();
57	  const body: ArtifactGenerationRequest = config.transformBody
58	    ? config.transformBody(rawBody)
59	    : rawBody;
60	
61	  if (!body.sourceText) {
62	    return NextResponse.json({ error: "sourceText is required" }, { status: 400 });
63	  }
64	
65	  const wantStream = Boolean(rawBody.stream);
66	  const userMessage = buildUserMessage(body);
67	
68	  // Streaming path: all artifact types use real token streaming.
69	  // JSON artifacts stream raw tokens for partial-JSON parsing on the client.
70	  if (wantStream) {
71	    const stream = streamLlm({
72	      endpoint: config.endpoint,
73	      systemPrompt: config.systemPrompt,
74	      userContent: userMessage,
75	      maxTokens: config.maxTokens ?? 8192,
76	      openRouterModel: OPENROUTER_MODEL,
77	    });
78	    return new Response(stream, { headers: SSE_HEADERS }) as unknown as NextResponse;
79	  }
80	
81	  try {
82	    const { text: responseText, usage, cacheKey } = await callLlm({
83	      endpoint: config.endpoint,
84	      systemPrompt: config.systemPrompt,
85	      userContent: userMessage,
86	      maxTokens: config.maxTokens ?? 8192,
87	      openRouterModel: OPENROUTER_MODEL,
88	      responseFormat: config.responseFormat,
89	    });
90	
91	    if (usage.provider === "mock") {
92	      return NextResponse.json({ [config.responseKey]: config.mockResponse(body.sourceText) });
93	    }
94	
95	    if (config.parseResponse === "text") {
96	      return NextResponse.json({ [config.responseKey]: responseText });
97	    }
98	
99	    try {
100	      const parsed = JSON.parse(stripCodeFences(responseText));
101	      return NextResponse.json({ [config.responseKey]: parsed });
102	    } catch {
103	      if (cacheKey) {
104	        try { await removeCachedResult(cacheKey.model, cacheKey.systemPrompt, cacheKey.userContent, cacheKey.maxTokens); } catch { /* ignore */ }
105	      }
106	      const preview = responseText.slice(0, 500);
107	      console.error(`[${config.endpoint}] Failed to parse LLM response as JSON:`, preview);
108	      return NextResponse.json(
109	        { error: "LLM response was not valid JSON", details: preview },
110	        { status: 502 },
111	      );
112	    }
113	  } catch (err) {
114	    if (err instanceof OpenRouterError) {
115	      return NextResponse.json(
116	        { error: err.message, details: err.details },
117	        { status: 502 },
118	      );
119	    }
120	    const message = err instanceof Error ? err.message : "Unknown error";
121	    console.error(`[${config.endpoint}] Unexpected error:`, message);
122	    return NextResponse.json(
123	      { error: `LLM call failed: ${message}` },
124	      { status: 502 },
125	    );
126	  }
127	}
