21	  allNodes: PropositionNode[],
22	  updateNode: (id: string, updates: Partial<PropositionNode>) => void,
23	  signal?: CancelSignal,
24	  artifactTypes?: ArtifactType[],
25	  contextText?: string,
26	): Promise<"verified" | "failed"> {
27	  // If no artifact types specified, default to legacy deductive pipeline
28	  const types = artifactTypes && artifactTypes.length > 0 ? artifactTypes : ["semiformal" as ArtifactType];
29	  const hasSemiformal = types.includes("semiformal");
30	  const nonDeductiveTypes = types.filter((t) => t !== "semiformal" && t !== "lean");
31	
32	  updateNode(node.id, { verificationStatus: "in-progress", verificationErrors: "" });
33	
34	  try {
35	    const nodeText = `${node.statement}\n\n${node.proofText}`;
36	    const context = node.context || contextText || "";
37	    let deductiveResult: "verified" | "failed" = "verified";
38	
39	    // Run deductive pipeline (semiformal → Lean → verify) if selected
40	    if (hasSemiformal) {
41	      const proof = await generateSemiformal(nodeText, context);
42	      if (signal?.cancelled) {
43	        updateNode(node.id, { verificationStatus: "unverified", verificationErrors: "" });
44	        return "failed";
45	      }
46	      updateNode(node.id, { semiformalProof: proof });
47	
48	      const depContext = gatherDependencyContext(allNodes, node.id);
49	      const result = await leanRetryLoop(proof, {
50	        onLeanCode: (code) => updateNode(node.id, { leanCode: code }),
51	        onErrors: (errors) => updateNode(node.id, { verificationErrors: errors }),
52	        isCancelled: () => signal?.cancelled ?? false,
53	        dependencyContext: depContext || undefined,
54	      });
55	
56	      if (signal?.cancelled) {
57	        updateNode(node.id, { verificationStatus: "unverified", verificationErrors: "" });
58	        return "failed";
59	      }
60	
61	      deductiveResult = result.valid ? "verified" : "failed";
62	    }
63	
64	    // Run non-deductive artifact generation in parallel
65	    if (nonDeductiveTypes.length > 0) {
66	      const request: ArtifactGenerationRequest = { sourceText: nodeText, context, nodeId: node.id, nodeLabel: node.label };
67	      const artifactResults = await generateNonDeductiveArtifacts(nonDeductiveTypes, request, signal);
68	
69	      if (signal?.cancelled) {
70	        updateNode(node.id, { verificationStatus: "unverified", verificationErrors: "" });
71	        return "failed";
72	      }
73	
74	      // Store artifacts on the node
75	      const newArtifacts: NodeArtifact[] = artifactResults.map(({ type, content }) => ({
76	        type,
77	        content: typeof content === "string" ? content : JSON.stringify(content),
78	        verificationStatus: "unverified" as const,
79	        verificationErrors: "",
80	      }));
81	
82	      if (newArtifacts.length > 0) {
83	        // Merge with existing artifacts, replacing any with the same type
84	        const existingArtifacts = (node.artifacts || []).filter(
85	          (a) => !newArtifacts.some((n) => n.type === a.type),
86	        );
87	        updateNode(node.id, { artifacts: [...existingArtifacts, ...newArtifacts] });
88	      }
89	    }
90	
91	    // Final status: use deductive result if semiformal was selected, otherwise mark as verified
92	    // (non-deductive artifacts don't have a verification step yet)
93	    const finalStatus = hasSemiformal ? deductiveResult : "verified";
94	    updateNode(node.id, {
95	      verificationStatus: finalStatus,
96	      verificationErrors: "",
97	    });
98	    return finalStatus;
99	  } catch (err) {
100	    const msg = err instanceof Error ? err.message : "Request failed";
101	    updateNode(node.id, { verificationStatus: "failed", verificationErrors: msg });
102	    return "failed";
103	  }
104	}
