106	/** Generate non-deductive artifacts by calling their API routes */
107	async function generateNonDeductiveArtifacts(
108	  types: ArtifactType[],
109	  request: ArtifactGenerationRequest,
110	  signal?: CancelSignal,
111	): Promise<Array<{ type: ArtifactType; content: unknown }>> {
112	  const promises = types.map(async (type): Promise<{ type: ArtifactType; content: unknown } | null> => {
113	    if (signal?.cancelled) return null;
114	    const route = ARTIFACT_ROUTE[type];
115	    if (!route) return null;
116	
117	    try {
118	      const data = await fetchApi<Record<string, unknown>>(route, request);
119	      const key = ARTIFACT_RESPONSE_KEY[type];
120	      return { type, content: data[key] ?? null };
121	    } catch (err) {
122	      console.error(`[formalizeNode:${type}]`, err);
123	      return null;
124	    }
125	  });
126	
127	  const results = await Promise.all(promises);
128	  return results.filter((r): r is NonNullable<typeof r> => r != null && r.content != null);
129	}
